(function () {
  'use strict';

  /* ------------------------------------------------------------------ *
   * 1. Section toggling
   * ------------------------------------------------------------------ */
  var sections = document.querySelectorAll('main section');
  var navLinks = document.querySelectorAll('nav a[href^="#"]');

  function updateNav(id) {
    var i;
    for (i = 0; i < navLinks.length; i += 1) {
      var link = navLinks[i];
      var targetId = link.getAttribute('href').substring(1);
      var label = link.getAttribute('data-label');

      if (!label) {
        label = link.textContent.replace(/\s*\(current\)$/, '');
        link.setAttribute('data-label', label);
      }

      if (targetId === id) {
        link.setAttribute('aria-current', 'page');
        link.textContent = label + ' (current)';
      } else {
        link.removeAttribute('aria-current');
        link.textContent = label;
      }
    }
  }

  function showSection(id) {
    var targetId = id;
    var i;

    if (!document.getElementById(targetId)) {
      targetId = sections[0] ? sections[0].id : id;
    }

    for (i = 0; i < sections.length; i += 1) {
      sections[i].hidden = (sections[i].id !== targetId);
    }

    updateNav(targetId);
  }

  function syncToHash() {
    var targetId = window.location.hash ? window.location.hash.substring(1) : '';
    showSection(targetId);
  }

  for (var l = 0; l < navLinks.length; l += 1) {
    navLinks[l].addEventListener('click', function () {
      var targetId = this.getAttribute('href').substring(1);
      showSection(targetId);
    });
  }

  window.addEventListener('hashchange', syncToHash);
  syncToHash();

  /* ------------------------------------------------------------------ *
   * 2. Contact form validation
   * ------------------------------------------------------------------ */
  var form = document.getElementById('contact-form');
  var nameField = document.getElementById('contact-name');
  var emailField = document.getElementById('contact-email');
  var messageField = document.getElementById('contact-message');
  var result = document.getElementById('form-result');

  function isValidEmail(value) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
  }

  if (form) {
    form.addEventListener('submit', function (event) {
      var name = nameField.value.trim();
      var email = emailField.value.trim();
      var message = messageField.value.trim();
      var errors = [];

      if (name === '') {
        errors.push('Please enter your name.');
      }
      if (email === '') {
        errors.push('Please enter your email address.');
      } else if (!isValidEmail(email)) {
        errors.push('Please enter a valid email address.');
      }
      if (message === '') {
        errors.push('Please enter a message.');
      }

      if (errors.length > 0) {
        // Block the mailto navigation so the page does not jump.
        event.preventDefault();
        result.textContent = errors.join(' ');
      } else {
        // Success message. The form still submits to action="mailto:[Email]",
        // which opens the visitor's mail client with the message pre-filled.
        result.textContent = 'Message ready — your mail client should open to send it.';
      }
    });
  }

  /* ------------------------------------------------------------------ *
   * 3. Footer year
   * ------------------------------------------------------------------ */
  var year = document.getElementById('year');
  if (year) {
    year.textContent = String(new Date().getFullYear());
  }
})();

